	private class SpyTableData : TestTableData<TestRowObject> {

		private int removeCount;
		private int insertCount;

		SpyTableData(List<TestRowObject> data, TableSortingContext<TestRowObject> sortContext) : base(data, sortContext)
    {
		}

		/* @Override */
		public bool remove(TestRowObject t) {
			removeCount++;
			return base.remove(t);
		}

		/* @Override */
		public void insert(TestRowObject value) {
			insertCount++;
			base.insert(value);
		}

		int getRemoveCount() {
			return removeCount;
		}

		int getInsertCount() {
			return insertCount;
		}
	}

	private class TestRowObject {

		private string name;
		private long id;

		TestRowObject(long id) {
			this.id = id;
			this.name = Long.toString(id);
		}

		string getName() {
			return name;
		}

		void setName(string newName) {
			this.name = newName;
		}

		/* @Override */
		public int hashCode() {
			return (int) id;
		}

		/* @Override */
		public bool equals(object obj) {
			if (this == obj) {
				return true;
			}
			if (obj == null) {
				return false;
			}
			if (getClass() != obj.GetType()) {
				return false;
			}

			TestRowObject other = (TestRowObject) obj;
			if (id != other.id) {
				return false;
			}
			return true;
		}

	}
